def mensagem_erro(status_code, erro=None):
    if status_code == 404:
        return 'Recurso não encontrado'
    if erro is not None and 'timed out' in str(erro).lower():
        return 'Timeout ao consultar a API'
    if status_code >= 500:
        return 'Erro interno do servidor'
    return 'Erro inesperado na API'
